layer.css:
[data-ryt="pitch"] { color: rgb(82, 89, 96); border-radius: 0px; font-family: -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, "helvetica neue", Arial, "noto sans", sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(82, 89, 96); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 16px; padding-right: 0px; padding-bottom: 0px; padding-left: 16px; transition: all; position: relative }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: rgb(0, 89, 179); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(0, 89, 179); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="pitch"]::before { content: ""; display: block; position: absolute; width: 4px; height: 96px; color: rgb(82, 89, 96); background-color: rgb(200, 204, 208); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 2px; font-family: -apple-system, BlinkMacSystemFont, "segoe ui", Roboto, "helvetica neue", Arial, "noto sans", sans-serif, "apple color emoji", "segoe ui emoji", "segoe ui symbol", "noto color emoji"; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(82, 89, 96); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: rgb(82, 89, 96); top: 0px; left: 0px }
